    out += "        var rgba: gdk.RGBA = undefined;\n";
    out += `        if (gdk.RGBA.parse(&rgba, dupeZ(propStr(props, "value") orelse ${zigDefaultStr(w, "value")})) != 0) gtk.ColorDialogButton.setRgba(btn, &rgba);\n`;
