/// M15 hand-written connect routes (webview-idiom: ONE call records the node
/// id; the widget's own code emits directly via ndEmitEvent). Keyed by the
/// SWIFT_SIGNALS selector string; emitted once per widget in ndConnectEvents.
const SWIFT_CUSTOM_CONNECT: Record<string, string> = {
  numberinput: "ndNumberInputConnect",
  linkbutton: "ndLinkButtonConnect",
  banner: "ndBannerConnect",
  popover: "ndPopoverConnect",
  expander: "ndExpanderConnect",
  fontpicker: "ndFontPickerConnect",
  toastoverlay: "ndToastOverlayConnect",
  table: "ndTableConnect",
  treeview: "ndTreeViewConnect",
  commandpalette: "ndCommandPaletteConnect",
  windowdialogs: "ndWindowDialogsConnect",
  windowtabs: "ndWindowTabsConnect",
  terminal: "ndTerminalConnect",
  hover: "ndHoverConnect",
  paned: "ndPanedConnect",
};

/** Emits `ndConnectEvents`, wiring each widget's controls to
 *  `EventDispatcher.shared` (target/action; Task 4 defines the class this
 *  references). Throws on any schema event without a template — the same
 *  fail-loud contract as `genZigEvents`. */
function genSwiftEvents(s: Schema): string {
  for (const w of s.widgets) for (const e of w.events) {
    const key = `${w.name}.${e.name}`;
    if (!SWIFT_SIGNALS[key]) {
      // Stubbed / platform-excluded widgets may lack signal templates; their
      // connect arms emit a marked no-op below instead of failing loud.
      if (swiftFallbackKind(w)) continue;
      throw new Error(`no signal template for event ${key} — add one when introducing it (M6b)`);
    }
  }

  let out = "func ndConnectEvents(_ view: NSView, _ kind: String, _ nodeID: UInt32) {\n";
  const withEvents = s.widgets.filter((w) => w.events.length > 0);
  if (withEvents.length === 0) {
    out += "    _ = view; _ = kind; _ = nodeID\n";
    out += "}\n\n";
    return out;
  }
  let first = true;
  for (const w of s.widgets) {
    if (w.events.length === 0) continue;
    out += `    ${first ? "if" : "} else if"} kind == ${JSON.stringify(w.name)} {\n`;
    first = false;
    let navConnected = false;
    const connectedSelectors = new Set<string>();
    for (const e of w.events) {
      const maybeT = SWIFT_SIGNALS[`${w.name}.${e.name}`];
      if (!maybeT) {
        // Guaranteed stubbed/excluded by the validation loop above.
        out += swiftFallbackKind(w) === "noop"
          ? `        // ND_PLATFORM_NOOP(${w.name}): "${e.name}" never fires on this platform.\n`
          : `        // ND_STUB(${w.name}): "${e.name}" event wiring pending the real AppKit implementation.\n`;
        continue;
      }
      const t = maybeT;
      if (t.selector === "menuitem") {
        out += "        ndMenuItemConnect(view, nodeID: nodeID) // M13: NSMenuItem target/action, not EventDispatcher\n";
        continue;
      }
      if (t.selector === "headerbarnav") {
        // back+forward both fire from one NSSegmentedControl — record the
        // nodeID once (the control's target/action is wired in ndHeaderBarApplyNav).
        if (!navConnected) {
          out += "        ndHeaderBarConnectNav(view, nodeID: nodeID)\n";
          navConnected = true;
        }
        continue;
      }
      if (t.selector === "nativeview") {
        // The retained core tree connects NativeView after create so it can pass nodeID.
        continue;
      }
      if (t.selector === "webview") {
        // All WebView events wire from KVO inside NDWebView — record the id once.
        if (!navConnected) {
          out += "        ndWebViewConnect(view, nodeID: nodeID)\n";
          navConnected = true;
        }
        continue;
      }
      if (SWIFT_CUSTOM_CONNECT[t.selector]) {
        // M15 hand-written connect: one call records the node id for every
        // event this widget emits directly (the webview idiom). Dedup is
        // per-selector, not per-widget — Window carries both windowdialogs
        // and windowtabs events.
        if (!connectedSelectors.has(t.selector)) {
          out += `        ${SWIFT_CUSTOM_CONNECT[t.selector]}(view, nodeID: nodeID)\n`;
          connectedSelectors.add(t.selector);
        }
        continue;
      }
      out += `        EventDispatcher.shared.wire(view, nodeID: nodeID, name: ${JSON.stringify(e.name)}, payload: .${t.payload}, action: #selector(EventDispatcher.${t.selector}(_:)))\n`;
    }
  }
  if (!first) out += "    }\n";
  out += "}\n\n";
  return out;
}

/** Per-widget bodies for the imperative widgetCommand dispatcher (M14) —
 *  AppKit peer of ZIG_COMMANDS, same fail-loud contract. Bodies see `view`,
 *  `command`, and `argJson`. */
const SWIFT_COMMANDS: Record<string, string> = {
  WebView: "        ndWebViewCommand(view, command, argJson)\n",
  Terminal: "        ndTerminalCommand(view, command, argJson)\n",
  // Dialogs resolve the owning NSWindow from the node's OWN handle
  // (ndWindow(for:)) — multi-window correct, no gWindow (M15). Tab commands
  // route to WindowTabs.swift first.
  Window: "        if command == \"showTabOverview\" || command == \"present\" { ndWindowTabsCommand(view, command, argJson); return }\n        ndWindowCommand(view, command, argJson)\n",
  ToastOverlay: "        ndToastOverlayCommand(view, command, argJson)\n",
};

function genSwiftCommands(s: Schema): string {
  let out = "/// App -> widget imperative commands (widgetCommand NDP frame, M14).\n";
  out += "func ndWidgetCommand(_ view: NSView, _ kind: String, _ command: String, _ argJson: String) {\n";
  const withCommands = s.widgets.filter((w) => (w.commands ?? []).length > 0);
  let first = true;
  for (const w of withCommands) {
    let body = SWIFT_COMMANDS[w.name];
    if (!body) {
      const fb = swiftFallbackKind(w);
      if (fb === "noop") {
        body = `        // ND_PLATFORM_NOOP(${w.name}): commands are no-ops on this platform.\n`;
      } else if (fb === "stub") {
        body = `        // ND_STUB(${w.name}): command dispatch pending the real AppKit implementation.\n        FileHandle.standardError.write("ND_STUB(${w.name}) widgetCommand \\(command) not implemented\\n".data(using: .utf8)!)\n`;
      } else {
        throw new Error(`no command template for widget ${w.name} — add one when introducing it (M14)`);
      }
    }
    out += `    ${first ? "if" : "} else if"} kind == ${JSON.stringify(w.name)} {\n`;
    out += body;
    first = false;
  }
  if (!first) {
    out += "    } else {\n";
    out += '        FileHandle.standardError.write("ND_WARN widgetCommand on kind=\\(kind) with no commands\\n".data(using: .utf8)!)\n';
    out += "    }\n";
  } else {
    out += '    FileHandle.standardError.write("ND_WARN widgetCommand on kind=\\(kind) with no commands\\n".data(using: .utf8)!)\n';
  }
  out += "}\n\n";
  return out;
}

interface SwiftStructuralTemplate {
  append: (childExpr: string) => string;
  insertBefore?: (childExpr: string, beforeExpr: string) => string;
  remove: (childExpr: string) => string;
}

// Shared between SplitView's append/insertBefore (identical body — slots
// aren't order-addressed, so `before` plays no part). M11 Phase C: the
// sidebar/content panes are now real NSSplitViewItems on the controller
// stashed at create time (SplitController.swift) — that's what earns the
// automatic Liquid Glass sidebar (floating glass pane on macOS 26, correct
// vibrancy pre-26) from one un-guarded code path, so there's no more manual
// NSVisualEffectView/NDPaneHostView wrapper or safe-area pin: the split view
// item itself supplies material, safe-area inset, and holding behavior.
const SPLITVIEW_STRUCTURAL_BODY =
  "        let split = parent as! NSSplitView\n" +
  "        let controller = ndSplitViewController(for: split)!\n" +
  // A ToolbarView pane is a LOGICAL holder: it merges its <headerbar>'s items
  // into the window toolbar (sidebar items left of the tracking separator,
  // content items right), but the pane VIEW never enters the hierarchy. Its
  // CONTENT box (an NSStackView) is what becomes the split item's view —
  // wrapped directly, exactly like a non-toolbarview child, so the item sizes
  // it to fill. (A plain-NSView pane wrapper would only hug its content's
  // intrinsic size, collapsing the pane to a narrow column.)
  "        var realChild = child\n" +
  "        if let pane = child as? NDToolbarPaneView {\n" +
  "            ndToolbarPaneAttachedToSplit(pane, split: split, slot: attachedSlot)\n" +
  "            realChild = pane.contentView ?? child\n" +
  "        }\n" +
  // ndMakePaneViewController (SplitController.swift) wraps realChild in a
  // flipped plain-NSView host pinned below the safe area: the split view
  // item supplies the material/glass, but nothing insets an NSStackView
  // below the titlebar of a fullSizeContentView window on its own — without
  // this pin, sidebar/editor content renders under the traffic lights
  // (measured: search-input at y=20). A plain NSView host does NOT block
  // the glass (unlike the old NSVisualEffectView wrapper).
  "        let vc = ndMakePaneViewController(realChild)\n" +
  '        if attachedSlot == "sidebar" {\n' +
  "            let item = NSSplitViewItem(sidebarWithViewController: vc)\n" +
  // `preferredThicknessFraction` only governs divider-double-click-reset and
  // fullscreen-enter sizing (Apple's own doc on the property), not the
  // FIRST layout — measured live: it had zero effect on initial width next
  // to a `list` item's hard `minimumThickness`, which the constraint solver
  // does honor immediately. An explicit floor keeps the sidebar a sane,
  // non-squeezed width the first time a three-pane split lays out.
  "            item.minimumThickness = 180\n" +
  "            if let fraction = splitViewSidebarFraction[ObjectIdentifier(split)] {\n" +
  "                item.preferredThicknessFraction = fraction\n" +
  "            }\n" +
  "            item.canCollapse = true\n" +
  "            item.isCollapsed = splitViewCollapsed[ObjectIdentifier(split)] ?? false\n" +
  "            controller.insertSplitViewItem(item, at: 0)\n" +
  // M13: the middle "folders / list / content" pane (Mail/Notes' message
  // list). NSSplitViewController natively supports a third contentList item
  // on the SAME controller — no nested controller needed (unlike the GTK
  // side, where AdwOverlaySplitView is strictly two-pane). Always inserted
  // right after the sidebar item (index 1) if one exists, else at index 0 —
  // this holds regardless of the three panes' mount order, since the sidebar
  // item always forces itself to index 0 and the content item always appends
  // at the tail (see the final `else` below).
  '        } else if attachedSlot == "list" {\n' +
  "            let item = NSSplitViewItem(contentListWithViewController: vc)\n" +
  "            item.minimumThickness = 240\n" +
  "            item.canCollapse = true\n" +
  "            if let fraction = splitViewListFraction[ObjectIdentifier(split)] {\n" +
  "                item.preferredThicknessFraction = fraction\n" +
  "            }\n" +
  "            let insertIndex = controller.splitViewItems.first?.behavior == .sidebar ? 1 : 0\n" +
  "            controller.insertSplitViewItem(item, at: insertIndex)\n" +
  "        } else {\n" +
  "            let item = NSSplitViewItem(viewController: vc)\n" +
  "            item.automaticallyAdjustsSafeAreaInsets = true\n" +
  "            controller.addSplitViewItem(item)\n" +
  "        }\n";

const SWIFT_STRUCTURAL: Record<string, SwiftStructuralTemplate> = {
  Window: {
    // `parent` here is the Window's tracked handle: the flipped contentView
    // itself (returned by the Window create arm) — reachable via
    // `parent.window` since it WAS the window's contentView at creation.
    // Window chrome on the Mac (M11 Phase B) is the unified NSToolbar the
    // pane <headerbar>s feed via the SplitView, not a window-level header
    // child — so there is no NDHeaderBarView branch here.
    //
    // M11 Phase C: a registered SplitView child must enter the window as
    // `contentViewController` (not a plain subview) — only that path earns
    // the automatic Liquid Glass sidebar treatment on macOS 26. This orphans
    // `parent` (Risk 1) — Backend.swift's get_window and Overlay.swift's
    // ndShowOverlay resolve the LIVE content via `contentViewController?.view`
    // first for this reason, and src/tree.zig's post-crash respawn path binds
    // the new Window node to whatever get_window returns, so that resolution
    // must stay live too. Any other child (counter/gallery, no split) keeps
    // the plain-subview path untouched.
    // `parent.window ?? gWindow`: once a split is installed as
    // contentViewController, `parent` (the create-arm FlippedView) is
    // orphaned and `parent.window` is nil — a REMOUNT (HMR / crash-restart
    // generation swap) must still find the window, so fall back to the
    // gWindow global. The non-split branch is self-healing for the same
    // reason: if a controller is still installed, clear it and re-seat
    // `parent` as contentView before parenting the plain child into it.
    append: () =>
      "        if ndMenuAttachToWindow(child) { return } // M13: a <menubar> child is app chrome (NSApp.mainMenu), not window content\n" +
      "        let window = parent.window ?? gWindow\n" +
      "        parent.subviews.forEach { $0.removeFromSuperview() }\n" +
      // A <toolbarview> directly under <window> (no SplitView): its header
      // items feed the SAME unified window toolbar the split panes use, so
      // the app's chrome row lives IN the titlebar with the traffic lights
      // inline — the AppKit peer of GTK's AdwToolbarView-as-window-content.
      // Its content box is what actually enters the hierarchy (the pane view
      // is a logical holder, same as in the SplitView arm), pinned below the
      // safe area so it clears the toolbar strip.
      "        if let pane = child as? NDToolbarPaneView {\n" +
      "            if let win = window, win.contentViewController != nil {\n" +
      "                win.contentViewController = nil\n" +
      "                win.contentView = parent\n" +
      "            }\n" +
      "            ndToolbarPaneAttachedToWindow(pane)\n" +
      "            let content = pane.contentView ?? pane\n" +
      "            parent.addSubview(content)\n" +
      "            content.translatesAutoresizingMaskIntoConstraints = false\n" +
      "            NSLayoutConstraint.activate([\n" +
      "                content.topAnchor.constraint(equalTo: parent.safeAreaLayoutGuide.topAnchor),\n" +
      "                content.leadingAnchor.constraint(equalTo: parent.leadingAnchor),\n" +
      "                content.trailingAnchor.constraint(equalTo: parent.trailingAnchor),\n" +
      "                content.bottomAnchor.constraint(equalTo: parent.bottomAnchor),\n" +
      "            ])\n" +
      "            return\n" +
      "        }\n" +
      // Frame save/reassert, preferredContentSize hazard, and the
      // attachForSidebar call all live in ndInstallSplitAsWindowContent
      // (SplitController.swift) — shared with the toastoverlay branch below.
      "        if let split = child as? NSSplitView, let controller = ndSplitViewController(for: split), let win = window {\n" +
      "            ndInstallSplitAsWindowContent(split, controller, win)\n" +
      // A <toastoverlay> wrapping a registered SplitView is a LOGICAL holder
      // on the Mac (its toasts are child-window NSPanels; the view draws
      // nothing), so the split it wraps must still take the exact
      // contentViewController path a direct <splitview> child takes — hosting
      // the bare splitView as a plain subview leaves every pane's content
      // hanging off the controller's never-installed wrapper view (measured:
      // the whole split subtree reports visible=false and renders nothing).
      // The overlay records the split at its own append (Toasts.swift's
      // setChild); this branch installs it and hands the overlay its host
      // window for panel presentation + automation visibility.
      '        } else if let overlay = child as? NDToastOverlayView, let split = overlay.ndEmbeddedSplit,\n' +
      "                  let controller = ndSplitViewController(for: split), let win = window {\n" +
      "            ndInstallSplitAsWindowContent(split, controller, win)\n" +
      "            overlay.ndHostWindow = win\n" +
      "        } else {\n" +
      "            if let win = window, win.contentViewController != nil {\n" +
      "                win.contentViewController = nil\n" +
      "                win.contentView = parent\n" +
      "            }\n" +
      // Plain (non-split) content respects the window safe area: in a
      // .fullSizeContentView window the contentView reaches the very top, so
      // a frame=bounds fill would put the app's first row of controls under
      // the floating traffic lights (observed: the browser example's back
      // button). SplitView panes get this pin from ndMakePaneViewController;
      // this is the same safe-area top pin for the plain-subview path. Only
      // the TOP goes through the guide — leading/trailing/bottom have no
      // window chrome to clear.
      "            parent.addSubview(child)\n" +
      "            child.translatesAutoresizingMaskIntoConstraints = false\n" +
      "            NSLayoutConstraint.activate([\n" +
      "                child.topAnchor.constraint(equalTo: parent.safeAreaLayoutGuide.topAnchor),\n" +
      "                child.leadingAnchor.constraint(equalTo: parent.leadingAnchor),\n" +
      "                child.trailingAnchor.constraint(equalTo: parent.trailingAnchor),\n" +
      "                child.bottomAnchor.constraint(equalTo: parent.bottomAnchor),\n" +
      "            ])\n" +
      "        }\n",
    // A registered split currently installed as contentViewController has no
    // superview to remove from (removeFromSuperview() would no-op or, worse,
    // reach into the window's private frame view) — clear
    // contentViewController instead so a later re-append can install a fresh
    // one cleanly (HMR remove+re-append of the root split).
    // Guard notes: compare CONTROLLERS, not `contentViewController?.view ===
    // child` — the controller's `view` is a distinct wrapper, never the
    // splitView handle (see SplitController.swift), so a view comparison is
    // dead code. And `parent.window` is nil in exactly this case (parent is
    // orphaned while a split is installed) — resolve via gWindow. After
    // clearing, re-seat `parent` as contentView so later appends of either
    // kind land in a live hierarchy.
    remove: () =>
      "        if ndIsMenuNode(child) { return } // M13: menubar detach is a no-op (mainMenu rebuilt on next change)\n" +
      "        if let pane = child as? NDToolbarPaneView {\n" +
      "            ndToolbarPaneDetachedFromSplit(pane) // same unregister path as the split arm\n" +
      "            (pane.contentView ?? pane).removeFromSuperview()\n" +
      "            return\n" +
      "        }\n" +
      "        if let split = child as? NSSplitView, let controller = ndSplitViewController(for: split),\n" +
      "           let window = parent.window ?? gWindow, window.contentViewController === controller {\n" +
      "            window.contentViewController = nil\n" +
      "            window.contentView = parent\n" +
      // Overlay-wrapped split (see the append arm): the installed controller
      // belongs to the overlay's embedded split — clear + re-seat exactly like
      // the direct-split branch above, and drop the overlay's window record.
      '        } else if let overlay = child as? NDToastOverlayView, let split = overlay.ndEmbeddedSplit,\n' +
      "                  let controller = ndSplitViewController(for: split),\n" +
      "                  let window = overlay.ndHostWindow ?? parent.window ?? gWindow, window.contentViewController === controller {\n" +
      "            window.contentViewController = nil\n" +
      "            window.contentView = parent\n" +
      "            overlay.ndHostWindow = nil\n" +
      "        } else {\n" +
      "            child.removeFromSuperview()\n" +
      "        }\n",
  },
  SettingsGroup: {
    append: () => "        let group = parent as! NDSettingsGroupView\n        group.appendReactView(child)\n",
    insertBefore: () =>
      "        let group = parent as! NDSettingsGroupView\n" +
      "        group.insertReactView(child, before: before)\n",
    remove: () => "        let group = parent as! NDSettingsGroupView\n        group.removeReactView(child)\n",
  },
  Box: {
    // Cross-axis "fill" + main-axis expand are both handled by
    // ndBoxChildAttached (Layout.swift), driven off the hexpand/vexpand/
    // halign/valign flags ndApplyStyle records per child.
    append: () => "        let stack = parent as! NSStackView\n        stack.addArrangedSubview(child)\n        ndBoxChildAttached(stack, child)\n",
    // The index must be computed on the child-less list: insertArrangedSubview(_:at:)
    // implicitly removes `child` first if it's already arranged, which shifts
    // `before`'s index down by one whenever child currently sits above it —
    // so detach child from its stale slot BEFORE finding `before`'s index
    // (mirrors src/tree.zig:156 recordInsertBefore's detach-first model).
    insertBefore: () =>
      "        let stack = parent as! NSStackView\n" +
      "        if stack.arrangedSubviews.contains(child) { stack.removeArrangedSubview(child) }\n" +
      "        let idx = stack.arrangedSubviews.firstIndex(of: before) ?? stack.arrangedSubviews.count\n" +
      "        stack.insertArrangedSubview(child, at: idx)\n" +
      "        ndBoxChildAttached(stack, child)\n",
    remove: () => "        let stack = parent as! NSStackView\n        stack.removeArrangedSubview(child)\n        ndBoxChildDetached(stack, child)\n        child.removeFromSuperview()\n",
  },
  ScrollView: {
    // childModel is "single" (schema/widgets.json): documentView itself is
    // never reassigned (create's FlippedView stays put, see genSwiftCreateBody)
    // — the child is pinned inside it instead, leading+trailing+top+bottom, so
    // its own intrinsic/fitting height drives the document's scrollable height
    // while the width tracks the clip view via doc's own constraints. Any
    // prior child is cleared first to preserve single-child semantics (mirrors
    // SWIFT_STRUCTURAL.Window's `parent.subviews.forEach { removeFromSuperview() }`).
    append: () =>
      "        let sv = parent as! NSScrollView\n" +
      "        let doc = sv.documentView!\n" +
      "        doc.subviews.forEach { $0.removeFromSuperview() }\n" +
      "        child.translatesAutoresizingMaskIntoConstraints = false\n" +
      "        doc.addSubview(child)\n" +
      "        NSLayoutConstraint.activate([\n" +
      "            child.leadingAnchor.constraint(equalTo: doc.leadingAnchor),\n" +
      "            child.trailingAnchor.constraint(equalTo: doc.trailingAnchor),\n" +
      "            child.topAnchor.constraint(equalTo: doc.topAnchor),\n" +
      "            child.bottomAnchor.constraint(equalTo: doc.bottomAnchor),\n" +
      "        ])\n",
    remove: () =>
      "        let sv = parent as! NSScrollView\n" +
      "        if child.superview === sv.documentView { child.removeFromSuperview() }\n",
  },
  Paned: {
    // Bare NSSplitView (not NSSplitViewController-based, unlike SplitView):
    // its subviews ARE the two panes in order, no item wrapping needed.
    // Every mutation re-applies the stored fraction: NSSplitView's
    // adjustSubviews would otherwise redistribute the panes 50/50 while the
    // JS-side position value is unchanged (PanedController.reapplyFraction).
    append: () =>
      "        let split = parent as! NSSplitView\n" +
      "        split.addSubview(child)\n" +
      "        ndPanedController(for: split)?.reapplyFraction()\n",
    // React commits deletions before placements, so a pane remount arrives as
    // insertBefore against the surviving pane; landing the child at `before`'s
    // index keeps the pane order (a plain addSubview appended it, swapping
    // the panes left/right).
    insertBefore: () =>
      "        let split = parent as! NSSplitView\n" +
      "        let idx = split.arrangedSubviews.firstIndex(of: before) ?? split.arrangedSubviews.count\n" +
      "        split.insertArrangedSubview(child, at: idx)\n" +
      "        ndPanedController(for: split)?.reapplyFraction()\n",
    remove: () =>
      "        let split = parent as! NSSplitView\n" +
      "        child.removeFromSuperview()\n" +
      "        ndPanedController(for: split)?.reapplyFraction()\n",
  },
  TabView: {
    append: () => "        let tabs = parent as! NSTabView\n        let item = NSTabViewItem()\n        item.view = child\n        item.label = attachedTabLabel\n        tabs.addTabViewItem(item)\n",
    insertBefore: () => "        let tabs = parent as! NSTabView\n        let item = NSTabViewItem()\n        item.view = child\n        item.label = attachedTabLabel\n        let idx = tabs.tabViewItems.firstIndex { $0.view === before } ?? tabs.tabViewItems.count\n        tabs.insertTabViewItem(item, at: idx)\n",
    remove: () => "        let tabs = parent as! NSTabView\n        if let item = tabs.tabViewItems.first(where: { $0.view === child }) {\n            tabs.removeTabViewItem(item)\n        }\n",
  },
  Grid: {
    append: () => "        let grid = parent as! NSGridView\n        ndGridPlace(grid, child, row: attachedGridRow, column: attachedGridColumn, rowSpan: attachedGridRowSpan, columnSpan: attachedGridColumnSpan)\n",
    insertBefore: () => "        // Grid children are position-addressed; sibling order is irrelevant.\n        let grid = parent as! NSGridView\n        ndGridPlace(grid, child, row: attachedGridRow, column: attachedGridColumn, rowSpan: attachedGridRowSpan, columnSpan: attachedGridColumnSpan)\n",
    remove: () => "        let grid = parent as! NSGridView\n        ndGridRemove(grid, child)\n",
  },
  SplitView: {
    // Two named slots, not an ordered list — insertBefore is set-by-slot, same
    // as append (mirrors the Zig STRUCTURAL.SplitView shape); `before` is
    // unused. NSSplitViewItem order is enforced regardless of mount order —
    // sidebar always inserted at index 0, content always appended at the end.
    append: () => SPLITVIEW_STRUCTURAL_BODY,
    insertBefore: () => SPLITVIEW_STRUCTURAL_BODY,
    remove: () =>
      "        let split = parent as! NSSplitView\n" +
      "        let controller = ndSplitViewController(for: split)!\n" +
      "        var realChild = child\n" +
      "        if let pane = child as? NDToolbarPaneView {\n" +
      "            ndToolbarPaneDetachedFromSplit(pane)\n" +
      "            realChild = pane.contentView ?? child\n" +
      "        }\n" +
      // realChild is directly a split view item's viewController.view now (no
      // wrapper) — find the owning item by that identity and remove it via
      // the controller so its NSSplitViewItem bookkeeping stays consistent.
      // The superview-removal fallback below only covers a non-item child
      // (shouldn't occur via the generated arms, kept for defense in depth).
      // realChild sits INSIDE the pane host view (ndMakePaneViewController),
      // so match by descendant, not view identity.
      "        if let item = controller.splitViewItems.first(where: { $0.viewController.view === realChild || realChild.isDescendant(of: $0.viewController.view) }) {\n" +
      "            controller.removeSplitViewItem(item)\n" +
      "        } else {\n" +
      "            split.removeArrangedSubview(realChild)\n" +
      "            realChild.removeFromSuperview()\n" +
      "        }\n",
  },
  HeaderBar: {
    append: () => '        ndHeaderBarPack(parent as! NDHeaderBarView, child, slot: attachedSlot)\n',
    insertBefore: () => '        ndHeaderBarPack(parent as! NDHeaderBarView, child, slot: attachedSlot)\n',
    remove: () => "        ndHeaderBarUnpack(parent as! NDHeaderBarView, child)\n",
  },
  ToolbarView: {
    // Child routing is by widget TYPE (like Window's HeaderBar check): a
    // <headerbar> child is recorded as the pane's header (its items feed the
    // window toolbar, tagged by pane slot, once the pane is in the split); any
    // other child becomes the pane's content view. `before` is irrelevant —
    // a pane has at most one header and one content child.
    append: () => "        ndToolbarPanePack(parent as! NDToolbarPaneView, child)\n",
    insertBefore: () => "        ndToolbarPanePack(parent as! NDToolbarPaneView, child)\n",
    remove: () => "        ndToolbarPaneUnpack(parent as! NDToolbarPaneView, child)\n",
  },
  // M13 menu containers: parent/child are NDMenuNodeView host handles. The
  // hand-written helpers link them into the menu model and schedule an
  // NDMenuManager rebuild. `before` is unused (menu order is the append order).
  Menubar: {
    append: () => "        ndMenuAppendChild(parent, child)\n",
    insertBefore: () => "        ndMenuAppendChild(parent, child)\n",
    remove: () => "        ndMenuRemoveChild(parent, child)\n",
  },
  Menu: {
    append: () => "        ndMenuAppendChild(parent, child)\n",
    insertBefore: () => "        ndMenuAppendChild(parent, child)\n",
    remove: () => "        ndMenuRemoveChild(parent, child)\n",
  },
  // M15: MenuButton/SplitButton/TrayItem children are Menu/MenuItem host
  // handles (NDMenuNodeView) — routed to the generalized NDMenuManager owner
  // registry, which rebuilds this owner's NSMenu on every structural change.
  MenuButton: {
    append: () => "        ndMenuOwnerAppend(parent, child)\n",
    insertBefore: () => "        ndMenuOwnerAppend(parent, child)\n",
    remove: () => "        ndMenuOwnerRemove(parent, child)\n",
  },
  SplitButton: {
    append: () => "        ndMenuOwnerAppend(parent, child)\n",
    insertBefore: () => "        ndMenuOwnerAppend(parent, child)\n",
    remove: () => "        ndMenuOwnerRemove(parent, child)\n",
  },
  TrayItem: {
    append: () => "        ndMenuOwnerAppend(parent, child)\n",
    insertBefore: () => "        ndMenuOwnerAppend(parent, child)\n",
    remove: () => "        ndMenuOwnerRemove(parent, child)\n",
  },
  // The popover's own single content child. (The popover ITSELF attaching to
  // its tree parent is the cross-cutting ndPopoverStructuralAttach guard at
  // the top of ndAppendChild/ndInsertBefore — parents don't need Popover arms.)
  Popover: {
    append: () => "        ndPopoverSetChild(parent, child)\n",
    remove: () => "        ndPopoverClearChild(parent, child)\n",
  },
  Expander: {
    append: () => "        (parent as! NDExpanderView).setContentChild(child)\n",
    remove: () => "        (parent as! NDExpanderView).clearContentChild(child)\n",
  },
  ToastOverlay: {
    append: () => "        ndToastOverlaySetChild(parent, child)\n",
    remove: () => "        ndToastOverlayClearChild(parent, child)\n",
  },
  // StatusPage fans its multi children (action buttons) into the actions
  // NSStackView below the hosted ContentUnavailableView (StatusPages.swift).
  StatusPage: {
    append: () => "        ndStatusPagePack(parent, child, before: nil)\n",
    insertBefore: () => "        ndStatusPagePack(parent, child, before: before)\n",
    remove: () => "        ndStatusPageUnpack(parent, child)\n",
  },
};

/** Emits `ndAppendChild`/`ndInsertBefore`/`ndRemoveChild`, one arm per
 *  container widget. Throws on a container without a structural template —
 *  the same fail-loud contract as `genZigStructural`. Attached-prop values
 *  (`tabLabel`, `gridRow`/`gridColumn`/`gridRowSpan`/`gridColumnSpan`) are
 *  decoded from `attachedJson` up front so every arm can read them by name. */
/** Structural no-op template for a stubbed / platform-excluded container —
 *  AppKit peer of `zigStubStructural` (children are created but never mounted;
 *  Menu children are NDMenuNodeView handles that must not enter the hierarchy). */
function swiftStubStructural(w: Widget, kind: "noop" | "stub"): SwiftStructuralTemplate {
  const mark = kind === "noop"
    ? `        // ND_PLATFORM_NOOP(${w.name}): children never mount on this platform.\n`
    : `        // ND_STUB(${w.name}): child mounting pending the real AppKit implementation.\n`;
  return { append: () => mark, remove: () => mark };
}

function genSwiftStructural(s: Schema): string {
  const containers = s.widgets.filter((w) => w.container !== null);
  const resolved: Record<string, SwiftStructuralTemplate> = {};
  for (const w of containers) {
    const t = SWIFT_STRUCTURAL[w.name];
    if (t) {
      resolved[w.name] = t;
      continue;
    }
    const fb = swiftFallbackKind(w);
    if (!fb) throw new Error(`no structural template for container widget ${w.name} — add one when introducing it (M6b)`);
    resolved[w.name] = swiftStubStructural(w, fb);
  }

  const attachedPrelude =
    "    let attached = parseProps(attachedJson)\n" +
    '    let attachedTabLabel = propStr(attached, "tabLabel") ?? ""\n' +
    '    let attachedGridRow = propInt(attached, "gridRow") ?? 0\n' +
    '    let attachedGridColumn = propInt(attached, "gridColumn") ?? 0\n' +
    '    let attachedGridRowSpan = propInt(attached, "gridRowSpan") ?? 1\n' +
    '    let attachedGridColumnSpan = propInt(attached, "gridColumnSpan") ?? 1\n' +
    '    let attachedSlot = propStr(attached, "slot") ?? "content"\n';

  let out = "func ndAppendChild(_ parent: NSView, _ parentKind: String, _ child: NSView, _ attachedJson: String) {\n";
  out += "    // Cross-cutting (M15): a Popover child anchors on its tree parent\n";
  out += "    // (never box-packed); a TrayItem is menu-bar chrome, never content.\n";
  out += "    if ndPopoverStructuralAttach(child, parent) { return }\n";
  out += "    if ndTrayItemStructuralAttach(child) { return }\n";
  out += attachedPrelude;
  let first = true;
  for (const w of containers) {
    out += `    ${first ? "if" : "} else if"} parentKind == ${JSON.stringify(w.name)} {\n`;
    first = false;
    out += resolved[w.name]!.append("child");
  }
  if (!first) out += "    } else {\n";
  else out += "    {\n";
  out += '        FileHandle.standardError.write("ND_WARN append to non-container kind=\\(parentKind)\\n".data(using: .utf8)!)\n';
  out += "    }\n";
  out += "}\n\n";

  out += "func ndInsertBefore(_ parent: NSView, _ parentKind: String, _ child: NSView, _ before: NSView?, _ attachedJson: String) {\n";
  out += "    // nil `before` degenerates to append everywhere (matches the M4 hand-written contract).\n";
  out += "    guard let before = before else { return ndAppendChild(parent, parentKind, child, attachedJson) }\n";
  out += "    // Cross-cutting (M15): Popover/TrayItem children are position-independent.\n";
  out += "    if ndPopoverStructuralAttach(child, parent) { return }\n";
  out += "    if ndTrayItemStructuralAttach(child) { return }\n";
  out += attachedPrelude;
  first = true;
  const withInsert = containers.filter((w) => resolved[w.name]!.insertBefore);
  for (const w of withInsert) {
    out += `    ${first ? "if" : "} else if"} parentKind == ${JSON.stringify(w.name)} {\n`;
    first = false;
    out += resolved[w.name]!.insertBefore!("child", "before");
  }
  if (!first) out += "    } else {\n";
  else out += "    {\n";
  out += "        // single-child containers: insertBefore degenerates to appendChild.\n";
  out += "        ndAppendChild(parent, parentKind, child, attachedJson)\n";
  out += "    }\n";
  out += "}\n\n";

  out += "func ndRemoveChild(_ parent: NSView, _ parentKind: String, _ child: NSView) {\n";
  out += "    // Cross-cutting (M15): detach an anchored Popover / tear down a\n";
  out += "    // TrayItem's NSStatusItem — neither was ever a layout child.\n";
  out += "    if ndPopoverStructuralDetach(child, parent) { return }\n";
  out += "    if ndTrayItemStructuralDetach(child) { return }\n";
  out += "    // Cross-cutting: deregister a torn-down `<paned>`'s controller (no-op\n";
  out += "    // unless `child` is itself a Paned's outer split view) — additive, not a\n";
  out += "    // short-circuit, since the split view still needs the ordinary\n";
  out += "    // removeFromSuperview dispatch below.\n";
  out += "    ndPanedTeardown(child)\n";
  first = true;
  for (const w of containers) {
    out += `    ${first ? "if" : "} else if"} parentKind == ${JSON.stringify(w.name)} {\n`;
    first = false;
    out += resolved[w.name]!.remove("child");
  }
  if (!first) out += "    } else {\n";
  else out += "    {\n";
  out += '        FileHandle.standardError.write("ND_WARN remove from non-container kind=\\(parentKind)\\n".data(using: .utf8)!)\n';
  out += "    }\n";
  out += "}\n";
  return out;
}

// ---- artifact (c): docs ----
function genDocs(s: Schema): string {
  let out = "<!-- GENERATED by tools/codegen.ts: do not edit -->\n\n";
  out += "# Widget reference\n\n";
  out += `Schema version: ${s.schemaVersion}. Generated from \`schema/widgets.json\`.\n\n`;
  for (const w of s.widgets) {
    out += `## ${w.name} (\`<${w.intrinsic}>\`)\n\n`;
    if (w.stub) out += `> **Stub.** Schema and API are defined, native implementations are pending. Renders an invisible placeholder.\n\n`;
    if (w.platforms) out += `> **Platforms:** ${w.platforms.join(", ")} only. An invisible no-op everywhere else.\n\n`;
    out += `Automation role: \`${w.automation.role}\`. `;
    out += `Text source: ${w.automation.textFrom ? "`" + w.automation.textFrom + "`" : "none"}. `;
    out += `Children: ${w.container ? w.container.childModel : "none"}.\n\n`;
    out += "| Prop | Type | Default | Applied |\n|---|---|---|---|\n";
    for (const p of w.props) {
      const type = p.type === "enum" ? (p.values ?? []).join(" \\| ") : p.type;
      const def = p.default === undefined ? "none" : String(p.default);
      out += `| \`${p.name}\` | ${type} | ${def} | ${p.appliesTo} |\n`;
    }
    out += "\n";
    if (w.events.length) {
      out += "| Event | Handler | Payload |\n|---|---|---|\n";
      for (const e of w.events) {
        out += `| \`${e.name}\` | \`${e.ndpName ?? e.name}\` | ${e.payload ?? "none"} |\n`;
      }
      out += "\n";
    }
    if ((w.commands ?? []).length) {
      out += `Imperative commands (via \`sendCommand(ref.current, …)\` from \`@nativedesktop/react\`): ${w.commands!.map((c) => "`" + c + "`").join(", ")}.\n\n`;
    }
    if (w.container?.attachedProps?.length) {
      out += "Attached props (set on children):\n\n";
      out += "| Prop | Type | Default |\n|---|---|---|\n";
      for (const ap of w.container.attachedProps) {
        out += `| \`${ap.name}\` | ${ap.type} | ${ap.default === undefined ? "none" : String(ap.default)} |\n`;
      }
      out += "\nAttached props apply at attach time only. Changing one after mount is a no-op.\n\n";
    }
    if (w.name === "Select") out += "`options` is create-only in v1.\n\n";
    if (w.name === "TabView") out += "`selectedIndex` takes effect on update; initial page is 0.\n\n";
    if (w.name === "Terminal") {
      out +=
        "`palette` carries the terminal's 16- or 256-color palette as a comma-separated list of `#rrggbb` hex colors, either 16 or 256 entries in ANSI index order (entry 0 is black, 1 red, up to 15 bright white for the 16-color form). Leave it unset for the backend's built-in default palette. `foreground` and `background` are the default text and cell colors, also `#rrggbb`, and are distinct from the `background` and `color` `style` props, which paint the widget's own view chrome rather than the terminal's cells.\n\n";
    }
  }
  return out;
}

// ---- artifact (e): styling reference ----
function genStyleDocs(s: Schema): string {
  let out = "<!-- GENERATED by tools/codegen.ts: do not edit -->\n\n";
  out += "# Styling\n\n";
  out += "`style` is an explicit, non-web prop on every widget. GTK styling is not web CSS: there is no `flex`, `grid`, `position`, `display`, or `justifyContent`. Layout comes from container widgets like `<box>` and `<grid>`, never from `style`. Unknown keys are rejected at the React renderer with a fix-it message, and rejected again host-side.\n\n";
  if (s.style) {
    out += "## Valid keys\n\n| Key | Shape | Compiles to |\n|---|---|---|\n";
    for (const [k, def] of Object.entries(s.style.keys)) {
      const shape = def.kind === "object" ? "object (" + Object.keys(def.fields ?? {}).join(", ") + ")" : def.kind;
      const to = def.target === "widget" ? "GTK widget property (not CSS)" : "GTK CSS (`" + (def.css ?? "nested") + "`)";
      out += `| \`${k}\` | ${shape} | ${to} |\n`;
    }
    out += "\n";
  }
  out += "## Why `margin` differs from `padding`\n\nGTK margins are widget properties (`gtk_widget_set_margin_*`) rather than CSS, so `margin` compiles to `setMarginStart`, `setMarginEnd`, `setMarginTop`, and `setMarginBottom`. `padding` is a real GTK CSS property, so it stays in the generated `.nd-<id>` CSS block alongside colors, fonts, and borders.\n\n";
  out += "## React item-templates for ListView\n\nNot implemented. `<listview>` renders native string rows today. Item-template components need the synchronous bind design from the widget spec before they can land.\n";
  return out;
}

// ---- artifact (f): binary NDP widgetType u16 table (ndp-binary spec §7) ----
// Schema declaration order, 1-based, value 0 reserved/invalid, NEVER renumbered or reused.
function genWidgetTypesTs(s: Schema): string {
  let out = HEADER_TS + "export const WIDGET_TYPE_RESERVED = 0;\n";
  out += "export const WIDGET_TYPE: Record<string, number> = {\n";
  for (let i = 0; i < s.widgets.length; i++) {
    out += `  ${s.widgets[i]!.name}: ${i + 1},\n`;
  }
  out += "};\n";
  return out;
}

function genWidgetTypesZig(s: Schema): string {
  let out = HEADER_ZIG + "const std = @import(\"std\");\n\n";
  out += "const Entry = struct { name: []const u8, value: u16, role: ?[]const u8 };\n";
  out += "pub const widget_types = [_]Entry{\n";
  for (let i = 0; i < s.widgets.length; i++) {
    const w = s.widgets[i]!;
    const role = w.automation?.role ? JSON.stringify(w.automation.role) : "null";
    out += `    .{ .name = ${JSON.stringify(w.name)}, .value = ${i + 1}, .role = ${role} },\n`;
  }
  out += "};\n\n";
  out += "pub fn widgetTypeOf(name: []const u8) ?u16 {\n";
  out += "    for (widget_types) |e| if (std.mem.eql(u8, e.name, name)) return e.value;\n";
  out += "    return null;\n}\n\n";
  out += "pub fn widgetNameOf(v: u16) ?[]const u8 {\n";
  out += "    for (widget_types) |e| if (e.value == v) return e.name;\n";
  out += "    return null;\n}\n\n";
  out += "/// The widget's schema-declared automation role (getTree's `role` field).\n";
  out += "pub fn roleOf(name: []const u8) ?[]const u8 {\n";
  out += "    for (widget_types) |e| if (std.mem.eql(u8, e.name, name)) return e.role;\n";
  out += "    return null;\n}\n";
  return out;
}

// ---- artifacts (g)+(h): NDP protocol frames + automation RPC (tRPC-style dual emission) ----
// schema/protocol.json and schema/rpc.json are the single sources of truth for
// the Zig<->Bun wire contracts that used to be hand-mirrored (src/protocol.zig
// vs runtime/ndp.ts; src/automation.zig vs packages/mcp). Both sides are
// emitted from the same schema, so a field rename or type change becomes a
// compile error on whichever side still uses the old shape instead of a
// silent runtime break. Zig field DECLARATION ORDER is wire byte order
// (std.json.Stringify emits struct fields in declaration order), so the
// schemas declare fields in the exact order the hand-written structs had.

type WireTypeName =
  | "u32" | "u64" | "i32" | "i64" | "f64" | "bool" | "string" | "stringList"
  | "object" // JSON object: TS Record<string, unknown>, Zig std.json.Value
  | "any" // arbitrary JSON: TS unknown, Zig std.json.Value
  | "widgetName" // widgets.json name union in TS; opaque string in Zig
  | "opList" // Op[] / []Op
  | (string & {}); // capitalized = reference to a schema-declared type

interface WireField {
  name: string;
  type: WireTypeName;
  /** omitted from the wire when unset (TS `?:`; Zig `?T = null` under emit_null_optional_fields=false) */
  optional?: boolean;
  /** the wire carries an explicit null (TS `T | null`; Zig `?T = null`) */
  nullable?: boolean;
  /** list of `type` (TS `T[]`; Zig `[]T`) */
  list?: boolean;
  default?: string | number | boolean | Record<string, never>;
  doc?: string;
}
interface WireStruct { name: string; doc?: string; fields: WireField[] }
interface OpDef { name: string; doc?: string; fields: WireField[] }
interface FrameDef {
  name: string;
  tsName: string;
  zigName: string;
  direction: "runtimeToHost" | "hostToRuntime";
  doc?: string;
  fields: WireField[];
}
interface ProtocolSchema { schemaVersion: number; ndpVersion: number; types: WireStruct[]; ops: OpDef[]; frames: FrameDef[] }
interface RpcErrorDef { name: string; code: number; message: string; doc?: string }
interface RpcMethodDef { name: string; doc?: string; params: WireField[]; result: string }
interface RpcSchema { schemaVersion: number; transport: string; types: WireStruct[]; methods: RpcMethodDef[]; errors: RpcErrorDef[] }

function assertKnownType(t: WireTypeName, declared: WireStruct[]): void {
  if (!declared.some((x) => x.name === t)) throw new Error(`unknown wire type ${JSON.stringify(t)}`);
}

function tsWireType(t: WireTypeName, declared: WireStruct[]): string {
  switch (t) {
    case "u32": case "u64": case "i32": case "i64": case "f64": return "number";
    case "bool": return "boolean";
    case "string": return "string";
    case "stringList": return "string[]";
    case "object": return "Record<string, unknown>";
    case "any": return "unknown";
    case "widgetName": return "WidgetName";
    case "opList": return "Op[]";
    default:
      assertKnownType(t, declared);
      return t;
  }
}

function zigWireType(t: WireTypeName, declared: WireStruct[]): string {
  switch (t) {
    case "u32": return "u32";
    case "u64": return "u64";
    case "i32": return "i32";
    case "i64": return "i64";
    case "f64": return "f64";
    case "bool": return "bool";
    case "string": return "[]const u8";
    case "stringList": return "[]const []const u8";
    case "object": case "any": return "std.json.Value";
    case "widgetName": return "[]const u8";
    case "opList": return "[]Op";
    default:
      assertKnownType(t, declared);
      return t;
  }
}

function tsWireField(f: WireField, declared: WireStruct[]): string {
  let base = tsWireType(f.type, declared);
  if (f.list) base += "[]";
  return `${f.name}${f.optional ? "?" : ""}: ${base}${f.nullable ? " | null" : ""}`;
}

function zigWireField(f: WireField, declared: WireStruct[]): string {
  let base = zigWireType(f.type, declared);
  if (f.list) base = `[]${base}`;
  if (f.optional || f.nullable) return `${f.name}: ?${base} = null`;
  if (f.default !== undefined) {
    if (typeof f.default === "object") return `${f.name}: ${base} = .{}`;
    if (typeof f.default === "string") return `${f.name}: ${base} = ${JSON.stringify(f.default)}`;
    return `${f.name}: ${base} = ${String(f.default)}`;
  }
  if (base === "std.json.Value") return `${f.name}: std.json.Value = .null`;
  return `${f.name}: ${base}`;
}

function zigDocLines(doc: string | undefined): string {
  if (!doc) return "";
  // Greedy word-wrap at ~96 columns so generated doc comments stay readable.
  const words = doc.split(/\s+/);
  const lines: string[] = [];
  let cur = "";
  for (const w of words) {
    if (cur.length > 0 && cur.length + 1 + w.length > 92) {
      lines.push(cur);
      cur = w;
    } else {
      cur = cur.length ? `${cur} ${w}` : w;
    }
  }
  if (cur.length) lines.push(cur);
  return lines.map((l) => `/// ${l}\n`).join("");
}

function tsDocLine(doc: string | undefined): string {
  return doc ? `/** ${doc} */\n` : "";
}

const ZIG_KEYWORDS = new Set([
  "align", "and", "anyframe", "anytype", "asm", "break", "catch", "comptime", "const", "continue",
  "defer", "else", "enum", "error", "export", "extern", "fn", "for", "if", "inline", "noalias",
  "opaque", "or", "orelse", "packed", "pub", "resume", "return", "struct", "suspend", "switch",
  "test", "threadlocal", "try", "type", "union", "unreachable", "var", "volatile", "while",
]);
function zigIdent(name: string): string {
  return ZIG_KEYWORDS.has(name) || !/^[A-Za-z_][A-Za-z0-9_]*$/.test(name) ? `@"${name}"` : name;
}
function camelToSnake(name: string): string {
  return name.replace(/[A-Z]/g, (m) => `_${m.toLowerCase()}`);
}
function capitalize(name: string): string {
  return name[0]!.toUpperCase() + name.slice(1);
}

// ---- artifact (g): NDP protocol frames ----
function genProtocolZig(s: ProtocolSchema): string {
  let out = HEADER_ZIG;
  out += "// Single source of truth: schema/protocol.json (consumed via src/protocol.zig,\n";
  out += "// which owns the framing/encode helpers). Field DECLARATION ORDER is wire byte\n";
  out += "// order — std.json.Stringify emits struct fields in declaration order — so\n";
  out += "// reordering fields here changes bytes on the wire.\n";
  out += "const std = @import(\"std\");\n\n";
  out += `pub const ndp_version: u32 = ${s.ndpVersion};\n\n`;
  for (const t of s.types) {
    out += zigDocLines(t.doc);
    out += `pub const ${t.name} = struct {\n`;
    for (const f of t.fields) out += `    ${zigWireField(f, s.types)},\n`;
    out += "};\n\n";
  }
  // The Zig Op is decode-side: one permissive struct whose optional fields
  // cover the union of all op shapes; the `op` string discriminates (the TS
  // side is the real discriminated union).
  const opFieldOwners = new Map<string, string[]>();
  const opFieldOrder: WireField[] = [];
  for (const op of s.ops) {
    for (const f of op.fields) {
      const owners = opFieldOwners.get(f.name);
      if (!owners) {
        opFieldOwners.set(f.name, [op.name]);
        opFieldOrder.push(f);
      } else {
        const first = opFieldOrder.find((x) => x.name === f.name)!;
        if (first.type !== f.type) throw new Error(`op field ${JSON.stringify(f.name)} redeclared with incompatible type (${first.type} vs ${f.type})`);
        owners.push(op.name);
      }
    }
  }
  out += `/// One of ${s.ops.map((o) => o.name).join("|")}. Decoded with a permissive struct:\n`;
  out += "/// optional fields cover the union of all op shapes; the `op` string discriminates.\n";
  out += "pub const Op = struct {\n";
  out += "    op: []const u8,\n";
  for (const f of opFieldOrder) {
    out += `    ${f.name}: ?${zigWireType(f.type, s.types)} = null, // ${opFieldOwners.get(f.name)!.join("/")}\n`;
  }
  out += "};\n\n";
  for (const fr of s.frames) {
    out += zigDocLines(fr.doc);
    out += `pub const ${fr.zigName} = struct {\n`;
    out += `    type: []const u8 = ${JSON.stringify(fr.name)},\n`;
    for (const f of fr.fields) out += `    ${zigWireField(f, s.types)},\n`;
    out += "};\n\n";
  }
  return out;
}

function genProtocolTs(s: ProtocolSchema, widgets: Schema): string {
  let out = HEADER_TS;
  out += "// Single source of truth: schema/protocol.json — the Zig mirror is\n";
  out += "// src/generated/protocol.zig. Field names are the wire contract with the\n";
  out += "// Zig host — verbatim, no renaming.\n\n";
  out += `export const NDP_VERSION = ${s.ndpVersion};\n\n`;
  // Same union genIntrinsics emits — duplicated here (from the same schema, so
  // no drift is possible) to keep this module dependency-free: runtime/ndp.ts
  // imports it and must not drag react types into the runtime's typecheck.
  out += "export type WidgetName = " + widgets.widgets.map((w) => JSON.stringify(w.name)).join(" | ") + ";\n\n";
  for (const t of s.types) {
    out += tsDocLine(t.doc);
    out += `export interface ${t.name} {\n`;
    for (const f of t.fields) out += `  ${tsWireField(f, s.types)};\n`;
    out += "}\n\n";
  }
  out += "export type Op =\n";
  out += s.ops
    .map((op) => `  | { op: ${JSON.stringify(op.name)}; ${op.fields.map((f) => tsWireField(f, s.types)).join("; ")} }`)
    .join("\n");
  out += ";\n\n";
  for (const fr of s.frames) {
    out += tsDocLine(fr.doc);
    out += `export interface ${fr.tsName} {\n`;
    out += `  type: ${JSON.stringify(fr.name)};\n`;
    for (const f of fr.fields) out += `  ${tsWireField(f, s.types)};\n`;
    out += "}\n\n";
  }
  const toHost = s.frames.filter((f) => f.direction === "runtimeToHost").map((f) => f.tsName);
  const toRuntime = s.frames.filter((f) => f.direction === "hostToRuntime").map((f) => f.tsName);
  out += `export type RuntimeToHostMsg = ${toHost.join(" | ")};\n`;
  out += `export type HostToRuntimeMsg = ${toRuntime.join(" | ")};\n`;
  return out;
}

// ---- artifact (h): automation RPC router (method -> params -> result -> error codes) ----
function genRpcZig(s: RpcSchema): string {
  let out = HEADER_ZIG;
  out += "// Single source of truth: schema/rpc.json (consumed by src/automation.zig).\n";
  out += `// Transport: ${s.transport}.\n`;
  out += "// Field DECLARATION ORDER in result structs is wire byte order.\n";
  out += "const std = @import(\"std\");\n\n";
  out += `pub const Method = enum { ${s.methods.map((m) => zigIdent(m.name)).join(", ")} };\n\n`;
  out += "const MethodEntry = struct { name: []const u8, method: Method };\n";
  out += "pub const method_table = [_]MethodEntry{\n";
  for (const m of s.methods) out += `    .{ .name = ${JSON.stringify(m.name)}, .method = .${zigIdent(m.name)} },\n`;
  out += "};\n\n";
  out += "pub fn methodFromString(name: []const u8) ?Method {\n";
  out += "    for (method_table) |e| if (std.mem.eql(u8, e.name, name)) return e.method;\n";
  out += "    return null;\n}\n\n";
  out += "// JSON-RPC error codes (+ the canonical message where one exists).\n";
  for (const e of s.errors) {
    const snake = camelToSnake(e.name);
    if (e.doc) out += `// ${e.name}: ${e.doc}\n`;
    out += `pub const code_${snake}: i32 = ${e.code};\n`;
    out += `pub const msg_${snake} = ${JSON.stringify(e.message)};\n`;
  }
  out += "\n";
  for (const t of s.types) {
    out += zigDocLines(t.doc);
    out += `pub const ${t.name} = struct {\n`;
    for (const f of t.fields) out += `    ${zigWireField(f, s.types)},\n`;
    out += "};\n\n";
  }
  // Params structs: every non-defaulted field is optional (`?T = null`) so the
  // dispatcher can answer a missing required param with the exact
  // "missing params.<x>" invalid-params message instead of a parse failure.
  for (const m of s.methods) {
    if (m.params.length === 0) continue;
    if (m.doc) out += zigDocLines(`${m.name}: ${m.doc}`);
    out += `pub const ${capitalize(m.name)}Params = struct {\n`;
    for (const f of m.params) {
      if (f.default !== undefined) {
        out += `    ${zigWireField(f, s.types)},\n`;
      } else {
        let base = zigWireType(f.type, s.types);
        if (f.list) base = `[]${base}`;
        out += `    ${f.name}: ?${base} = null,\n`;
      }
    }
    out += "};\n\n";
  }
  return out;
}

function genRpcTs(s: RpcSchema): string {
  let out = HEADER_TS;
  out += "// Single source of truth: schema/rpc.json — the Zig mirror is\n";
  out += "// src/generated/rpc.zig (consumed by src/automation.zig). Typed client:\n";
  out += "// packages/mcp/src/socket.ts constrains AutomationClient.call with the\n";
  out += "// RpcMethods map below, tRPC-style.\n\n";
  for (const t of s.types) {
    out += tsDocLine(t.doc);
    out += `export interface ${t.name} {\n`;
    for (const f of t.fields) out += `  ${tsWireField(f, s.types)};\n`;
    out += "}\n\n";
  }
  for (const m of s.methods) {
    if (m.params.length === 0) continue;
    out += tsDocLine(m.doc);
    out += `export interface ${capitalize(m.name)}Params {\n`;
    for (const f of m.params) {
      const opt = f.optional || f.default !== undefined;
      let base = tsWireType(f.type, s.types);
      if (f.list) base += "[]";
      out += `  ${f.name}${opt ? "?" : ""}: ${base};\n`;
    }
    out += "}\n\n";
  }
  out += "export interface RpcMethods {\n";
  for (const m of s.methods) {
    const params = m.params.length === 0 ? "undefined" : `${capitalize(m.name)}Params`;
    out += `  ${m.name}: { params: ${params}; result: ${m.result} };\n`;
  }
  out += "}\n";
  out += "export type RpcMethodName = keyof RpcMethods;\n";
  out += "export type RpcParams<M extends RpcMethodName> = RpcMethods[M][\"params\"];\n";
  out += "export type RpcResult<M extends RpcMethodName> = RpcMethods[M][\"result\"];\n\n";
  out += "export const RPC_ERRORS = {\n";
  for (const e of s.errors) {
    if (e.doc) out += `  /** ${e.doc} */\n`;
    out += `  ${e.name}: { code: ${e.code}, message: ${JSON.stringify(e.message)} },\n`;
  }
  out += "} as const;\n";
  return out;
}

async function writeIfChanged(rel: string, content: string): Promise<void> {
  const path = resolve(ROOT, rel);
  await Bun.write(path, content);
  console.log("wrote", rel, `(${content.length} bytes)`);
}

const schema = (await Bun.file(resolve(ROOT, "schema/widgets.json")).json()) as Schema;
// Every objectList `itemShape` must reference a declared top-level type, and
// no widget prop may shadow a cross-cutting prop codegen injects into every
// intrinsic (e.g. DatePicker's display style had to be `displayStyle`).
{
  const typeNames = new Set((schema.types ?? []).map((t) => t.name));
  const reserved = new Set(["style", "cssClasses", "key", "ref", "children"]);
  for (const w of schema.widgets) for (const p of w.props) {
    if (p.itemShape && !typeNames.has(p.itemShape)) {
      throw new Error(`${w.name}.${p.name}: itemShape ${JSON.stringify(p.itemShape)} is not declared in widgets.json "types"`);
    }
    if (reserved.has(p.name)) {
      throw new Error(`${w.name}.${p.name}: ${JSON.stringify(p.name)} is a reserved cross-cutting prop name — pick another (e.g. displayStyle)`);
    }
  }
}
await writeIfChanged("packages/react/src/generated/intrinsics.ts", genIntrinsics(schema));
await writeIfChanged("packages/react/src/generated/schema-meta.ts", genSchemaMeta(schema));
await writeIfChanged("src/generated/widgets.zig", genZig(schema));
await writeIfChanged("docs/widgets.md", genDocs(schema));
await writeIfChanged("docs/styling.md", genStyleDocs(schema));
await writeIfChanged("swift/Sources/NDGen/Widgets.swift", genSwift(schema));
await writeIfChanged("packages/react/src/generated/widget-types.ts", genWidgetTypesTs(schema));
await writeIfChanged("src/generated/widget_types.zig", genWidgetTypesZig(schema));

const protocolSchema = (await Bun.file(resolve(ROOT, "schema/protocol.json")).json()) as ProtocolSchema;
await writeIfChanged("packages/react/src/generated/protocol.ts", genProtocolTs(protocolSchema, schema));
await writeIfChanged("src/generated/protocol.zig", genProtocolZig(protocolSchema));

const rpcSchema = (await Bun.file(resolve(ROOT, "schema/rpc.json")).json()) as RpcSchema;
await writeIfChanged("packages/react/src/generated/rpc.ts", genRpcTs(rpcSchema));
await writeIfChanged("src/generated/rpc.zig", genRpcZig(rpcSchema));
console.log("codegen complete");
